mapper.select:
select id, event_id, actor_kind, actor_member_id, actor_member_type, actor_role_id,
    target_type, target_id, action_code, reason,
    before_data, after_data,
    result_status, error_code, created_at
from member_operation_log

    and id = #{id}
    and actor_member_id = #{actorMemberId}
    and actor_role_id = #{actorRoleId}
    and actor_kind = #{actorKind}
    and target_type = #{targetType}
    and target_id = #{targetId}
    and action_code = #{actionCode}
    and result_status = #{resultStatus}
    and created_at >= #{createdFrom}
    and created_at <= #{createdTo}

order by created_at desc, id desc
